 "content": "def transform(grid):
    """Connect collinear occurrences of the rare foreground color with 3s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    marks = [v for row in grid for v in row if v != bg]
    if not marks:
        return out
    mark = max(set(marks), key=marks.count)
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
